import 'dart:math' as math;

import 'package:flutter/material.dart';

/// MiliConfig's metallic neon emblem: a dark angular M with a green rim, inside a thin
/// green ring and a tilted orbital ring, on a deep black-green field. Matches the launcher
/// icon (images/icon/, generated by scripts/make_brand_assets.py).
class MiliShieldLogo extends StatelessWidget {
  final double size;
  final Color? primaryColor;
  final Color? accentColor;

  const MiliShieldLogo({
    super.key,
    this.size = 28,
    this.primaryColor,
    this.accentColor,
  });

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final primary = primaryColor ?? scheme.primary;
    final accent = accentColor ?? scheme.secondary;
    return SizedBox(
      width: size,
      height: size,
      child: CustomPaint(
        painter: _NeonEmblemPainter(primary: primary, accent: accent),
      ),
    );
  }
}

class _NeonEmblemPainter extends CustomPainter {
  final Color primary;
  final Color accent;

  const _NeonEmblemPainter({required this.primary, required this.accent});

  static const _leftBlade = [
    (238.0, 205.0),
    (168.0, 770.0),
    (334.0, 610.0),
    (300.0, 300.0),
  ];
  static const _rightBlade = [
    (786.0, 205.0),
    (856.0, 770.0),
    (690.0, 610.0),
    (724.0, 300.0),
  ];
  static const _v = [(238.0, 205.0), (512.0, 730.0), (786.0, 205.0)];
  static const _orbitAngle = -18 * math.pi / 180;
  static const _orbitCenter = Offset(512, 500);
  static const _orbitRadius = (392.0, 158.0);

  Path _polygon(List<(double, double)> points, double s) {
    final path = Path()..moveTo(points.first.$1 * s, points.first.$2 * s);
    for (final p in points.skip(1)) {
      path.lineTo(p.$1 * s, p.$2 * s);
    }
    return path..close();
  }

  Path _vPath(double s) {
    final path = Path()
      ..moveTo(_v[0].$1 * s, _v[0].$2 * s)
      ..lineTo(_v[1].$1 * s, _v[1].$2 * s)
      ..lineTo(_v[2].$1 * s, _v[2].$2 * s);
    return path;
  }

  @override
  void paint(Canvas canvas, Size size) {
    // Leave a real launcher-style margin around the emblem instead of letting the ring and
    // orbit touch the circular/adaptive mask. The script uses the same idea for the assets.
    final s = size.shortestSide / 1024.0 * 0.84;
    final dx = (size.width - 1024 * s) / 2;
    final dy = (size.height - 1024 * s) / 2;
    double w(double design) => math.max(1.0, design * s);
    final contentRect = Rect.fromLTWH(0, 0, 1024 * s, 1024 * s);
    final center = Offset.zero & size;

    // Deep green halo behind the mark.
    canvas.drawCircle(
      center.center,
      size.shortestSide * 0.48,
      Paint()
        ..shader = RadialGradient(
          colors: [
            primary.withValues(alpha: 0.16),
            const Color(0xFF03140A).withValues(alpha: 0.45),
            Colors.transparent,
          ],
          stops: const [0, 0.66, 1],
        ).createShader(
          Rect.fromCircle(center: center.center, radius: size.shortestSide * 0.48),
        ),
    );

    canvas.save();
    canvas.translate(dx, dy);
    final cx = 512 * s;
    final cy = 512 * s;

    // Outer ring: bloom then a crisp neon line.
    final ringRadius = 356 * s;
    for (final blur in [10.0, 4.0]) {
      canvas.drawCircle(
        Offset(cx, cy),
        ringRadius,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = w(blur > 6 ? 12.0 : 7.0)
          ..color = primary.withValues(alpha: blur > 6 ? 0.25 : 0.42)
          ..maskFilter = MaskFilter.blur(BlurStyle.normal, w(blur)),
      );
    }
    canvas.drawCircle(
      Offset(cx, cy),
      ringRadius,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = w(4.2)
        ..color = Color.lerp(primary, Colors.white, 0.25)!,
    );

    // The orbit's back half sits behind the M; the front half is painted after it.
    _orbit(canvas, s, front: false);
    _drawM(canvas, s, contentRect);
    _orbit(canvas, s, front: true);
    canvas.restore();
  }

  void _drawM(Canvas canvas, double s, Rect rect) {
    double w(double design) => math.max(1.0, design * s);
    final left = _polygon(_leftBlade, s);
    final right = _polygon(_rightBlade, s);
    final v = _vPath(s);
    final vWidth = 120 * s;
    final centerTip = _polygon(
      const [(470.0, 685.0), (512.0, 805.0), (554.0, 685.0)],
      s,
    );

    // Bloom behind all metal.
    for (final path in [left, right]) {
      canvas.drawPath(
        path,
        Paint()
          ..color = primary.withValues(alpha: 0.32)
          ..maskFilter = MaskFilter.blur(BlurStyle.normal, 14 * s),
      );
    }
    canvas.drawPath(
      v,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = vWidth + w(18)
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round
        ..color = primary.withValues(alpha: 0.40)
        ..maskFilter = MaskFilter.blur(BlurStyle.normal, w(12)),
    );

    // A soft drop shadow gives the blades their thickness.
    canvas.save();
    canvas.translate(16 * s, 20 * s);
    final shadowPaint = Paint()
      ..color = const Color(0xFF000503).withValues(alpha: 0.85)
      ..maskFilter = MaskFilter.blur(BlurStyle.normal, w(10));
    canvas.drawPath(left, shadowPaint);
    canvas.drawPath(right, shadowPaint);
    canvas.drawPath(
      v,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = vWidth
        ..strokeJoin = StrokeJoin.round
        ..color = const Color(0xFF000503).withValues(alpha: 0.85),
    );
    canvas.restore();

    // Green edge of the V, then its dark metal face on top.
    canvas.drawPath(
      centerTip,
      Paint()..color = primary,
    );
    canvas.drawPath(
      v,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = vWidth + w(10)
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round
        ..color = primary,
    );
    canvas.drawPath(
      v,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = vWidth
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round
        ..shader = const LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [Color(0xFF245238), Color(0xFF07120C)],
        ).createShader(rect),
    );

    // The two blades: lit left face, shadowed right face, bright rim.
    for (final (path, tint) in [
      (left, 0.04),
      (right, 0.0),
    ]) {
      canvas.drawPath(
        path,
        Paint()
          ..shader = LinearGradient(
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
            colors: [
              Color.lerp(const Color(0xFF2A6042), const Color(0xFF0A1A11), tint)!,
              const Color(0xFF06100A),
            ],
          ).createShader(rect),
      );
      canvas.drawPath(
        path,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = w(7)
          ..strokeJoin = StrokeJoin.round
          ..color = primary,
      );
    }

    // A darker inset edge on the inner V, with a silver ridge down its centre.
    canvas.drawPath(
      centerTip,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = w(7)
        ..color = primary,
    );
    canvas.drawPath(
      v,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = w(3.2)
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round
        ..color = Color.lerp(accent, Colors.white, 0.55)!,
    );
    canvas.drawPath(
      centerTip,
      Paint()
        ..color = const Color(0xFF0A1A11),
    );
    canvas.drawPath(
      centerTip,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = w(5)
        ..color = primary,
    );

    // Two glints on the peaks.
    for (final x in [238.0, 786.0]) {
      canvas.drawCircle(
        Offset(x * s, 210 * s),
        w(7),
        Paint()
          ..color = const Color(0xFFE4FFE9).withValues(alpha: 0.8)
          ..maskFilter = MaskFilter.blur(BlurStyle.normal, w(2)),
      );
    }
  }

  void _orbit(Canvas canvas, double s, {required bool front}) {
    double w(double design) => math.max(1.0, design * s);
    const start = math.pi;
    final rect = Rect.fromCenter(
      center: Offset(_orbitCenter.dx * s, _orbitCenter.dy * s),
      width: _orbitRadius.$1 * 2 * s,
      height: _orbitRadius.$2 * 2 * s,
    );
    canvas.save();
    canvas.translate(_orbitCenter.dx * s, _orbitCenter.dy * s);
    canvas.rotate(_orbitAngle);
    canvas.translate(-_orbitCenter.dx * s, -_orbitCenter.dy * s);
    final sweep = math.pi;
    final offset = front ? 0.0 : start;

    for (final blur in [9.0, 3.0]) {
      canvas.drawArc(
        rect,
        offset,
        sweep,
        false,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = w(blur > 5 ? 15.0 : 9.0)
          ..strokeCap = StrokeCap.round
          ..color = primary.withValues(alpha: blur > 5 ? 0.25 : 0.42)
          ..maskFilter = MaskFilter.blur(BlurStyle.normal, w(blur)),
      );
    }
    canvas.drawArc(
      rect,
      offset,
      sweep,
      false,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = w(6)
        ..strokeCap = StrokeCap.round
        ..shader = SweepGradient(
          colors: [
            Color.lerp(primary, Colors.white, 0.35)!,
            primary,
            const Color(0xFF0B5A22),
            primary,
            Color.lerp(primary, Colors.white, 0.35)!,
          ],
        ).createShader(rect),
    );
    canvas.restore();
  }

  @override
  bool shouldRepaint(_NeonEmblemPainter oldDelegate) =>
      oldDelegate.primary != primary || oldDelegate.accent != accent;
}

/// A slow-rotating conic sheen, clipped to [size]; used by the setup wizard hero.
class NeonSheen extends StatelessWidget {
  final double size;
  final Color color;
  final double turns;
  const NeonSheen({
    super.key,
    required this.size,
    required this.color,
    this.turns = 0,
  });

  @override
  Widget build(BuildContext context) {
    return Transform.rotate(
      angle: turns * 2 * math.pi,
      child: Container(
        width: size,
        height: size,
        decoration: BoxDecoration(
          shape: BoxShape.circle,
          gradient: SweepGradient(
            colors: [
              color.withValues(alpha: 0.35),
              Colors.transparent,
              color.withValues(alpha: 0.18),
              Colors.transparent,
            ],
          ),
        ),
      ),
    );
  }
}
